mod earcut;

use std::io::Write;

/// Replicates C `atoi` semantics: skip leading whitespace, optional sign,
/// then decimal digits; stops at the first non-digit; no digits -> 0.
fn atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        if b[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut val: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        val = val.wrapping_mul(10).wrapping_add((b[i] - b'0') as i64);
        i += 1;
    }
    sign.wrapping_mul(val) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 2;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let nf = n as f64;
    let mut polygon: Vec<Vec<(f64, f64)>> = Vec::new();
    polygon.push(vec![(0.0, 0.0), (nf, 0.0), (nf, nf), (0.0, nf)]);
    if n > 1 {
        polygon.push(vec![
            (0.25 * nf, 0.25 * nf),
            (0.75 * nf, 0.25 * nf),
            (0.75 * nf, 0.75 * nf),
            (0.25 * nf, 0.75 * nf),
        ]);
    }

    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for i in indices {
        print!("{} ", i);
    }
    out.flush().unwrap();
}

