//! Pure-Rust port of the mapbox `earcut` polygon triangulation algorithm
//! (ear clipping with hole bridging and a z-order curve hashing fallback).
//!
//! Nodes live in an arena (`Vec<Node>`) and are linked by indices, mirroring
//! the pointer-based doubly linked lists of the C++ implementation. Removed
//! nodes are only unlinked, never destroyed, exactly like the C++ pool
//! allocator, so stale links keep the same semantics as the original.

const NIL: usize = usize::MAX;

#[derive(Clone)]
struct Node {
    i: u32, // vertex index in the original polygon
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    // z-order curve linked list
    z: i32,
    prev_z: usize,
    next_z: usize,
    steiner: bool,
}

pub struct Earcut {
    pub indices: Vec<u32>,
    nodes: Vec<Node>,
    inv_size: f64,
    min_x: f64,
    min_y: f64,
}

/// Triangulate a polygon given as a list of rings (outer ring first, then
/// holes). Returns triangle indices into the flattened vertex list.
pub fn earcut(polygon: &[Vec<(f64, f64)>]) -> Vec<u32> {
    let mut e = Earcut {
        indices: Vec::new(),
        nodes: Vec::new(),
        inv_size: 0.0,
        min_x: 0.0,
        min_y: 0.0,
    };
    e.run(polygon);
    e.indices
}

impl Earcut {
    fn run(&mut self, points: &[Vec<(f64, f64)>]) {
        if points.is_empty() {
            return;
        }

        let mut len = 0usize;
        for ring in points {
            len += ring.len();
        }

        let outer_node = match self.linked_list(&points[0], 0, true) {
            Some(n) => n,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        let mut start_node = outer_node;
        if points.len() > 1 {
            start_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        if len > 80 {
            let mut min_x = points[0][0].0;
            let mut min_y = points[0][0].1;
            let mut max_x = min_x;
            let mut max_y = min_y;

            for ring in points {
                for p in ring {
                    if p.0 < min_x {
                        min_x = p.0;
                    }
                    if p.1 < min_y {
                        min_y = p.1;
                    }
                    if p.0 > max_x {
                        max_x = p.0;
                    }
                    if p.1 > max_y {
                        max_y = p.1;
                    }
                }
            }

            // min_x, min_y and inv_size are later used to transform coords into
            // integers for z-order calculation
            self.min_x = min_x;
            self.min_y = min_y;
            let size = (max_x - min_x).max(max_y - min_y);
            self.inv_size = if size != 0.0 { 32767.0 / size } else { 0.0 };
        }

        self.earcut_linked(start_node, 0);
    }

    // create a circular doubly linked list from polygon points in the
    // specified winding order
    fn linked_list(&mut self, ring: &[(f64, f64)], start: usize, clockwise: bool) -> Option<usize> {
        let mut last: Option<usize> = None;
        let end = ring.len();

        if clockwise == (signed_area(ring) > 0.0) {
            for i in 0..end {
                last = Some(self.insert_node((start + i) as u32, ring[i].0, ring[i].1, last));
            }
        } else {
            for i in (0..end).rev() {
                last = Some(self.insert_node((start + i) as u32, ring[i].0, ring[i].1, last));
            }
        }

        if let Some(l) = last {
            if self.equals(l, self.nodes[l].next) {
                self.remove_node(l);
                last = Some(self.nodes[l].next);
            }
        }

        last
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: usize, end: Option<usize>) -> usize {
        let mut end = end.unwrap_or(start);

        let mut p = start;
        loop {
            let mut again = false;

            let next = self.nodes[p].next;
            let prev = self.nodes[p].prev;
            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }
        end
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(&mut self, mut ear: usize, pass: i32) {
        let hashing = self.inv_size != 0.0;

        // interlink polygon nodes in z-order
        if pass == 0 && hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let filtered = self.filter_points(ear, None);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small self-intersections locally
                    let filtered = self.filter_points(ear, None);
                    ear = self.cure_local_intersections(filtered);
                    self.earcut_linked(ear, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon into two
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != self.nodes[ear].prev {
            if point_in_triangle(
                self.nodes[a].x,
                self.nodes[a].y,
                self.nodes[b].x,
                self.nodes[b].y,
                self.nodes[c].x,
                self.nodes[c].y,
                self.nodes[p].x,
                self.nodes[p].y,
            ) && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = self.nodes[a].x.min(self.nodes[b].x).min(self.nodes[c].x);
        let min_ty = self.nodes[a].y.min(self.nodes[b].y).min(self.nodes[c].y);
        let max_tx = self.nodes[a].x.max(self.nodes[b].x).max(self.nodes[c].x);
        let max_ty = self.nodes[a].y.max(self.nodes[b].y).max(self.nodes[c].y);

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;
        while p != NIL && self.nodes[p].z <= max_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(
                    self.nodes[a].x,
                    self.nodes[a].y,
                    self.nodes[b].x,
                    self.nodes[b].y,
                    self.nodes[c].x,
                    self.nodes[c].y,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;
        while p != NIL && self.nodes[p].z >= min_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(
                    self.nodes[a].x,
                    self.nodes[a].y,
                    self.nodes[b].x,
                    self.nodes[b].y,
                    self.nodes[c].x,
                    self.nodes[c].y,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut p = start;
        let mut start = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            // a self-intersection where edge (a,p) intersects (p->next,b)
            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                self.remove_node(p);
                let pn = self.nodes[p].next;
                self.remove_node(pn);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        p
    }

    // try splitting polygon into two and triangulate them independently
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let an = self.nodes[a].next;
                    self.filter_points(a, Some(an));
                    let cn = self.nodes[c].next;
                    self.filter_points(c, Some(cn));

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // link every hole into the outer loop, producing a single-ring polygon without holes
    fn eliminate_holes(&mut self, points: &[Vec<(f64, f64)>], outer_node: usize) -> usize {
        let mut queue: Vec<usize> = Vec::new();

        let mut start = points[0].len();
        for ring in points.iter().skip(1) {
            if let Some(list) = self.linked_list(ring, start, false) {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
            start += ring.len();
        }
        queue.sort_by(|&a, &b| {
            self.nodes[a]
                .x
                .partial_cmp(&self.nodes[b].x)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // process holes from left to right
        let mut start_node = outer_node;
        for &hole in &queue {
            if let Some(h) = self.eliminate_hole(hole, outer_node) {
                start_node = h;
            }
        }
        start_node
    }

    // find a bridge between vertices that connects hole with an outer ring
    // and link it
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> Option<usize> {
        let bridge = self.find_hole_bridge(hole, outer_node)?;

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let brn = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, Some(brn));

        Some(hole)
    }

    // David Eberly's algorithm for finding a bridge between hole and outer polygon
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> Option<usize> {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m: Option<usize> = None;

        // find a segment intersected by a ray from the hole's leftmost point to the left;
        // segment's endpoint with lesser x will be potential connection point
        loop {
            let pn = self.nodes[p].next;
            if hy <= self.nodes[p].y && hy >= self.nodes[pn].y && self.nodes[pn].y != self.nodes[p].y
            {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y) * (self.nodes[pn].x - self.nodes[p].x)
                        / (self.nodes[pn].y - self.nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    if x == hx {
                        if hy == self.nodes[p].y {
                            return Some(p);
                        }
                        if hy == self.nodes[pn].y {
                            return Some(pn);
                        }
                    }
                    m = Some(if self.nodes[p].x < self.nodes[pn].x { p } else { pn });
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        let mut m = m?;

        // hole touches outer segment; pick lower endpoint
        if hx == qx {
            return Some(m);
        }

        // look for points inside the triangle of hole point, segment intersection and endpoint;
        // if there are no points found, we have a valid connection;
        // otherwise choose the point of the minimum angle with the ray as connection point
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        p = self.nodes[m].next;
        while p != stop {
            if hx >= self.nodes[p].x
                && self.nodes[p].x >= mx
                && hx != self.nodes[p].x
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
            {
                let tan_cur = (hy - self.nodes[p].y).abs() / (hx - self.nodes[p].x); // tangential

                if (tan_cur < tan_min || (tan_cur == tan_min && self.nodes[p].x > self.nodes[m].x))
                    && self.locally_inside(p, hole)
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }
            p = self.nodes[p].next;
        }

        Some(m)
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                self.nodes[p].z = self.z_order(self.nodes[p].x, self.nodes[p].y);
            }
            let prev = self.nodes[p].prev;
            let next = self.nodes[p].next;
            self.nodes[p].prev_z = prev;
            self.nodes[p].next_z = next;
            p = next;
            if p == start {
                break;
            }
        }

        let pz = self.nodes[p].prev_z;
        self.nodes[pz].next_z = NIL;
        self.nodes[p].prev_z = NIL;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    // http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_linked(&mut self, list: usize) -> usize {
        let mut list = list;
        let mut in_size = 1;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NIL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NIL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    // z-order of a point given coords and size of the data bounding box
    fn z_order(&self, x: f64, y: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x - self.min_x) * self.inv_size) as i32;
        let mut y = ((y - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF_00FF;
        x = (x | (x << 4)) & 0x0F0F_0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF_00FF;
        y = (y | (y << 4)) & 0x0F0F_0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }

    // find the leftmost node of a polygon ring
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    // check if a diagonal between two polygon nodes is valid (lies in polygon interior)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let a_next = self.nodes[a].next;
        let a_prev = self.nodes[a].prev;
        let b_prev = self.nodes[b].prev;
        self.nodes[a_next].i != self.nodes[b].i
            && self.nodes[a_prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(a_prev, a, b_prev) != 0.0 || self.area(a, b_prev, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(a_prev, a, a_next) > 0.0
                    && self.area(b_prev, b, self.nodes[b].next) > 0.0))
    }

    // signed area of a triangle
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    // check if two points are equal
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2)) || (self.equals(p1, q2) && self.equals(p2, q1))
        {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let a_prev = self.nodes[a].prev;
        let a_next = self.nodes[a].next;
        if self.area(a_prev, a, a_next) < 0.0 {
            self.area(a, b, a_next) >= 0.0 && self.area(a, a_prev, b) >= 0.0
        } else {
            self.area(a, b, a_prev) < 0.0 || self.area(a, a_next, b) < 0.0
        }
    }

    // check if the middle point of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            if (self.nodes[p].y > py) != (self.nodes[pn].y > py)
                && self.nodes[pn].y != self.nodes[p].y
                && px
                    < (self.nodes[pn].x - self.nodes[p].x) * (py - self.nodes[p].y)
                        / (self.nodes[pn].y - self.nodes[p].y)
                        + self.nodes[p].x
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    // link two polygon vertices with a bridge; if the vertices belong to the
    // same ring, it splits polygon into two; if one belongs to the outer ring
    // and another to a hole, it merges it into a single ring
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.create_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.create_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    // create a node and optionally link it with previous one (in a circular doubly linked list)
    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
        let p = self.create_node(i, x, y);

        match last {
            None => {
                self.nodes[p].prev = p;
                self.nodes[p].next = p;
            }
            Some(last) => {
                let ln = self.nodes[last].next;
                self.nodes[p].next = ln;
                self.nodes[p].prev = last;
                self.nodes[ln].prev = p;
                self.nodes[last].next = p;
            }
        }
        p
    }

    fn create_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        let idx = self.nodes.len();
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: idx,
            next: idx,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        });
        idx
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let pz = self.nodes[p].prev_z;
        let nz = self.nodes[p].next_z;
        if pz != NIL {
            self.nodes[pz].next_z = nz;
        }
        if nz != NIL {
            self.nodes[nz].prev_z = pz;
        }
    }
}

// signed area of a ring (positive for counter-clockwise winding)
fn signed_area(ring: &[(f64, f64)]) -> f64 {
    let mut sum = 0.0;
    let mut j = ring.len() - 1;
    for i in 0..ring.len() {
        sum += (ring[j].0 - ring[i].0) * (ring[i].1 + ring[j].1);
        j = i;
    }
    sum
}

// check if a point lies within a convex triangle
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) >= (ax - px) * (cy - py)
        && (ax - px) * (by - py) >= (bx - px) * (ay - py)
        && (bx - px) * (cy - py) >= (cx - px) * (by - py)
}

