mod earcut;

use std::io::Write;

/// Replicates C `atoi` semantics: skip leading whitespace, accept an optional
/// sign, then consume digits; anything else yields 0 and trailing garbage is
/// ignored. Overflow is approximated with wrapping arithmetic.
fn atoi(s: &str) -> i64 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val.wrapping_mul(10).wrapping_add((bytes[i] - b'0') as i64);
        i += 1;
    }
    sign.wrapping_mul(val)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: i32 = if args.len() == 1 {
        2
    } else {
        atoi(&args[1]) as i32
    };
    let nf = n as f64;

    let mut polygon: Vec<Vec<(f64, f64)>> = Vec::new();
    polygon.push(vec![(0.0, 0.0), (nf, 0.0), (nf, nf), (0.0, nf)]);
    if n > 1 {
        let q = 0.25 * nf;
        let t = 0.75 * nf;
        polygon.push(vec![(q, q), (t, q), (t, t), (q, t)]);
    }

    let indices = earcut::earcut(&polygon);

    for idx in &indices {
        print!("{} ", idx);
    }
    let _ = std::io::stdout().flush();
}

